def set_cell_size(text: str, total: int) -> str:
    """Set the length of a string to fit within given number of cells."""

    if _is_single_cell_widths(text):
        size = len(text)
        if size < total:
            return text + " " * (total - size)
        return text[:total]

    if total <= 0:
        return ""
    cell_size = cell_len(text)
    if cell_size == total:
        return text
    if cell_size < total:
        return text + " " * (total - cell_size)

    graphemes = list(iter_graphemes(text))
    current_width = 0
    result = []
    for g in graphemes:
        g_width = get_character_cell_size(g[0]) if len(g) == 1 else 2
        if current_width + g_width <= total:
            result.append(g)
            current_width += g_width
        else:
            break

    final_text = "".join(result)
    if current_width < total:
        final_text += " " * (total - current_width)
    return final_text
